"""`.Hair alpha mask parser`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Hair alpha mask parser'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Value', 'NodeSocketFloat')
    t.socket('INPUT', 'Alpha mask', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Alpha mask (alpha)', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Main texture (plain alpha)', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)

    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (191.2067, 0.0),
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-201.20668, 0.0),
    })
    t.node('ShaderNodeRGBToBW', 'RGB to BW', props={
        'location': (1.2066879, 34.05475),
        'hide': True,
    })
    t.node('ShaderNodeMath', 'Math', props={
        'location': (0.42356873, -0.61395264),
        'hide': True,
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.001', props={
        'location': (-1.2066803, -34.05475),
        'hide': True,
        'operation': 'MULTIPLY',
    })

    t.link('Math', 'Value', 'Math.001', 'Value')
    t.link('RGB to BW', 'Val', 'Math', 'Value')
    t.link('Group Input', 'Alpha mask', 'RGB to BW', 'Color')
    t.link('Group Input', 'Main texture (plain alpha)', 'Math.001', 'Value_001')
    t.link('Group Input', 'Alpha mask (alpha)', 'Math', 'Value_001')
    t.link('Math.001', 'Value', 'Group Output', 'Value')
    return t
